PARAM_MAP = {
    'spindle_speed_rpm': ('tool_spindleSpeed', 1.0),      # direct, no conversion
    'feed_cutting_mm_min': ('tool_feedCutting', 0.1),      # mm/min → cm/min
    'feed_ramp_mm_min': ('tool_feedEntry', 0.1),
    'max_stepdown_mm': ('maximumStepdown', 0.1),           # mm → cm
    'max_stepover_mm': ('maximumStepover', 0.1),
    'tolerance_mm': ('tolerance', 0.1),
    'stock_to_leave_mm': ('stockToLeave', 0.1),
}
for prism_key, (fusion_key, factor) in PARAM_MAP.items():
    val = params.get(prism_key)
    if val is not None:
        try:
            p = operation.parameters.itemByName(fusion_key)
            if p:
                p.expression = str(val * factor)
        except: pass
